import{_ as a,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"TS-AI 全栈分层架构","description":"用交互、应用、Agent、工作流、数据与基础设施六层描述 TypeScript 全栈 AI 系统，并以售后与知识库场景说明职责与依赖方向。","frontmatter":{"title":"TS-AI 全栈分层架构","description":"用交互、应用、Agent、工作流、数据与基础设施六层描述 TypeScript 全栈 AI 系统，并以售后与知识库场景说明职责与依赖方向。","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture.md","filePath":"ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture.md","lastUpdated":1786166505000}'),d={name:"ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture.md"};function r(l,t,i,o,p,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="ts-ai-全栈分层架构" tabindex="-1">TS-AI 全栈分层架构 <a class="header-anchor" href="#ts-ai-全栈分层架构" aria-label="Permalink to &quot;TS-AI 全栈分层架构&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>把 Nuxt Chat、Nest API、LangChain Agent、LangGraph 审批图和 Postgres 表混在一张「系统图」里时，讨论会立刻滑向实现细节。本篇建立<strong>决策层分层模型</strong>：每一层回答一类问题，层与层之间只有明确依赖方向。读完应能在白板上画出六层，并指出「流式气泡」「工单 Tool」「审批 Interrupt」「Run 行」各自归属。</p><p>本篇不展开各包 API。框架职责细节见 <a href="/ts-ai/architecture/design-decisions/framework-boundaries">Nuxt、NestJS、LangChain 与 LangGraph 的边界</a>；状态真伪见 <a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a>；Chain / Agent / Workflow 选型见 <a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a>。</p><h2 id="_1-定义与问题边界" tabindex="-1">1. 定义与问题边界 <a class="header-anchor" href="#_1-定义与问题边界" aria-label="Permalink to &quot;1. 定义与问题边界&quot;">​</a></h2><h3 id="_1-1-分层要解决什么" tabindex="-1">1.1 分层要解决什么 <a class="header-anchor" href="#_1-1-分层要解决什么" aria-label="Permalink to &quot;1.1 分层要解决什么&quot;">​</a></h3><p>全栈 AI 系统同时存在多种「执行」：</p><table tabindex="0"><thead><tr><th>现象</th><th>若不分层会发生什么</th></tr></thead><tbody><tr><td>用户看到半截流式字</td><td>UI 临时态与服务端 Run 终态纠缠</td></tr><tr><td>模型调用失败</td><td>业务 Service 与供应商 SDK 互相耦合</td></tr><tr><td>退款审批挂起两天</td><td>对话 Agent 循环被硬塞进审批状态机</td></tr><tr><td>知识库引用丢权限</td><td>检索逻辑散落在前端与 Prompt 中</td></tr></tbody></table><p>分层的目标不是多画几个框，而是让<strong>变更半径可预测</strong>：换模型供应商不应改 Nuxt 组件；改审批节点不应改 Message 表 Schema；改气泡样式不应改 Checkpoint。</p><h3 id="_1-2-本篇包含与排除" tabindex="-1">1.2 本篇包含与排除 <a class="header-anchor" href="#_1-2-本篇包含与排除" aria-label="Permalink to &quot;1.2 本篇包含与排除&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包含</th><th>排除</th></tr></thead><tbody><tr><td>六层职责、依赖方向、跨层契约</td><td>Nest Controller / SSE 帧实现 → <a href="/ts-ai/backend/">服务端</a></td></tr><tr><td>售后与知识库在层上的落点</td><td>RAG 索引管道细节 → <a href="/ts-ai/knowledge/">知识</a></td></tr><tr><td>最小可验证的分层自检</td><td>LangGraph 节点 API → <a href="/ts-ai/workflow/">工作流</a></td></tr></tbody></table><p>贯穿场景默认两条升级路径之一：<strong>售后执行（含审批）</strong> 或 <strong>企业知识库助手</strong>；两者共享同一套分层，只是 Agent / 工作流 / 数据层的权重不同。</p><h2 id="_2-六层组成及其关系" tabindex="-1">2. 六层组成及其关系 <a class="header-anchor" href="#_2-六层组成及其关系" aria-label="Permalink to &quot;2. 六层组成及其关系&quot;">​</a></h2><h3 id="_2-1-层一览" tabindex="-1">2.1 层一览 <a class="header-anchor" href="#_2-1-层一览" aria-label="Permalink to &quot;2.1 层一览&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. 交互层   Nuxt Chat / 审批面板 / 引用卡 │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 2. 应用层   Nest 用例、鉴权、租户、协议适配 │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 3. Agent 层  createAgent / Tool / Prompt │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 4. 工作流层  LangGraph StateGraph / HITL │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 5. 数据层   Thread·Run·Message·业务实体  │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 6. 基础设施 模型网关·队列·缓存·可观测·密钥 │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>依赖方向：<strong>自上而下调用，自下而上提供能力</strong>。禁止交互层直接持有模型 Key，禁止数据层反向依赖 Nuxt 组件类型。</p><h3 id="_2-2-层间契约-决策级" tabindex="-1">2.2 层间契约（决策级） <a class="header-anchor" href="#_2-2-层间契约-决策级" aria-label="Permalink to &quot;2.2 层间契约（决策级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>从 → 到</th><th>契约形态</th><th>例子（售后）</th></tr></thead><tbody><tr><td>交互 → 应用</td><td>HTTP / SSE 产品事件</td><td><code>POST /runs</code>、<code>token.delta</code></td></tr><tr><td>应用 → Agent</td><td>内部端口（输入、context、abort）</td><td><code>supportAgent.stream(input, ctx)</code></td></tr><tr><td>应用 → 工作流</td><td>启动图 / resume / cancel</td><td><code>refundGraph.invoke(..., thread_id)</code></td></tr><tr><td>Agent / 工作流 → 数据</td><td>读写业务事实与审计</td><td>查工单、写退款单、落 Message</td></tr><tr><td>各层 → 基础设施</td><td>模型别名、队列、Trace</td><td><code>gateway.resolve(&#39;support-fast&#39;)</code></td></tr></tbody></table><p>应用层是<strong>对外稳定面</strong>：前端只认识产品协议；Agent 与工作流是对内编排面。</p><h2 id="_3-各层职责" tabindex="-1">3. 各层职责 <a class="header-anchor" href="#_3-各层职责" aria-label="Permalink to &quot;3. 各层职责&quot;">​</a></h2><h3 id="_3-1-交互层" tabindex="-1">3.1 交互层 <a class="header-anchor" href="#_3-1-交互层" aria-label="Permalink to &quot;3.1 交互层&quot;">​</a></h3><p>负责把服务端事实与流式增量变成可理解的界面。</p><table tabindex="0"><thead><tr><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>气泡渲染、输入框、工具卡、审批按钮</td><td>决定用哪个模型别名</td></tr><tr><td>本地连接态、乐观占位、滚动与无障碍</td><td>持久化 Thread / Run</td></tr><tr><td>按事件幂等更新 UI</td><td>执行 Tool 副作用</td></tr></tbody></table><p>Nuxt 侧典型归属：<code>pages</code>、<code>components/chat</code>、<code>composables/useAgentChat</code>。细节见 <a href="/ts-ai/integration/">全栈集成</a>。</p><h3 id="_3-2-应用层" tabindex="-1">3.2 应用层 <a class="header-anchor" href="#_3-2-应用层" aria-label="Permalink to &quot;3.2 应用层&quot;">​</a></h3><p>NestJS 承载用例边界：鉴权、租户、幂等、创建 Run、映射流式事件、调用 Agent 或图。</p><table tabindex="0"><thead><tr><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>REST / SSE 边界、DTO、Guard</td><td>Prompt 文案创意本身</td></tr><tr><td>将身份写入 Runtime Context</td><td>在 Controller 里拼 LCEL 链</td></tr><tr><td>把框架事件适配成产品事件</td><td>直接 <code>new ChatOpenAI</code> 散落各处</td></tr></tbody></table><p>应用层回答「<strong>这次请求允不允许、记成哪次 Run、对外暴露什么事件</strong>」。</p><h3 id="_3-3-agent-层" tabindex="-1">3.3 Agent 层 <a class="header-anchor" href="#_3-3-agent-层" aria-label="Permalink to &quot;3.3 Agent 层&quot;">​</a></h3><p>LangChain.js 组件与 <code>createAgent</code> Harness：模型、工具、中间件、有限轮次的自主循环。</p><table tabindex="0"><thead><tr><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>工具选择与多轮推理（有预算）</td><td>跨天审批挂起</td></tr><tr><td>结构化输出、Guardrails</td><td>业务表权威状态</td></tr><tr><td>与 Model Gateway 解析出的 ChatModel 协作</td><td>浏览器会话 Cookie</td></tr></tbody></table><p>售后场景：短问答、查工单、建议话术 → Agent 层足够。需要「人工审批后退款」→ 升到工作流层。</p><h3 id="_3-4-工作流层" tabindex="-1">3.4 工作流层 <a class="header-anchor" href="#_3-4-工作流层" aria-label="Permalink to &quot;3.4 工作流层&quot;">​</a></h3><p>LangGraph.js 显式状态图：节点、边、Checkpoint、Interrupt、Resume。</p><table tabindex="0"><thead><tr><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>持久控制流、并行分支、HITL</td><td>Chat 气泡样式</td></tr><tr><td>图内中间 State 恢复</td><td>替代 Postgres 业务单据</td></tr><tr><td>与应用层约定 resume 令牌</td><td>替代 Model Gateway</td></tr></tbody></table><p>知识库主路径通常<strong>不强制</strong>重图；售后审批路径几乎总需要本层。选型依据见 Agent / Chain / Workflow 边界文。</p><h3 id="_3-5-数据层" tabindex="-1">3.5 数据层 <a class="header-anchor" href="#_3-5-数据层" aria-label="Permalink to &quot;3.5 数据层&quot;">​</a></h3><p>业务与会话的权威存储：Thread、Run、Message、工单、退款单、知识文档元数据与权限。</p><table tabindex="0"><thead><tr><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>可查询、可审计的事实</td><td>流式连接是否在线</td></tr><tr><td>租户隔离与保留策略</td><td>模型采样参数</td></tr><tr><td>与 Checkpoint 的边界声明</td><td>把 UI 乐观态当真相</td></tr></tbody></table><p>表模型见 <a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread、Run 与 Message 数据模型</a>；Redis 辅助态见 <a href="/ts-ai/backend/data-tasks/redis-state-ownership">Redis 与状态所有权</a>。</p><h3 id="_3-6-基础设施层" tabindex="-1">3.6 基础设施层 <a class="header-anchor" href="#_3-6-基础设施层" aria-label="Permalink to &quot;3.6 基础设施层&quot;">​</a></h3><p>跨用例共享能力：Model Gateway、密钥、队列（BullMQ）、缓存、限流、OpenTelemetry、配置中心。</p><table tabindex="0"><thead><tr><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>模型别名交付、默认超时</td><td>按用户话术动态选模型策略细节（属路由 ADR / agent 文）</td></tr><tr><td>可观测挂钩、密钥注入</td><td>业务用例分支</td></tr><tr><td>Worker 与重试底座</td><td>产品事件字段命名</td></tr></tbody></table><p>网关<strong>为何存在</strong>见 <a href="/ts-ai/architecture/design-decisions/model-gateway">模型网关</a>；Nest 实现见 <a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a>。</p><h2 id="_4-核心运行机制-一次请求如何穿过六层" tabindex="-1">4. 核心运行机制：一次请求如何穿过六层 <a class="header-anchor" href="#_4-核心运行机制-一次请求如何穿过六层" aria-label="Permalink to &quot;4. 核心运行机制：一次请求如何穿过六层&quot;">​</a></h2><h3 id="_4-1-售后短问答-无审批" tabindex="-1">4.1 售后短问答（无审批） <a class="header-anchor" href="#_4-1-售后短问答-无审批" aria-label="Permalink to &quot;4.1 售后短问答（无审批）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：「工单 T-10086 状态？」</span></span>
<span class="line"><span>  交互：发送，显示 pending 气泡</span></span>
<span class="line"><span>  应用：鉴权 → 创建 Run(queued→running) → 打开 SSE</span></span>
<span class="line"><span>  Agent：createAgent + queryTicket Tool</span></span>
<span class="line"><span>  工作流：不进入</span></span>
<span class="line"><span>  数据：写 user/assistant Message；Run → completed</span></span>
<span class="line"><span>  基础：gateway.resolve(&#39;support-fast&#39;)</span></span>
<span class="line"><span>  交互：apply token.delta / run.completed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_4-2-售后退款审批-升层" tabindex="-1">4.2 售后退款审批（升层） <a class="header-anchor" href="#_4-2-售后退款审批-升层" aria-label="Permalink to &quot;4.2 售后退款审批（升层）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：「对 T-10086 退款 199」</span></span>
<span class="line"><span>  交互：同上</span></span>
<span class="line"><span>  应用：创建 Run，调用 refundGraph 而非纯 Agent</span></span>
<span class="line"><span>  Agent：可作为图内节点（起草说明、调用只读 Tool）</span></span>
<span class="line"><span>  工作流：risk_check → interrupt(approval) → execute_refund</span></span>
<span class="line"><span>  数据：退款单 status=pending_approval；Checkpoint 保存图位置</span></span>
<span class="line"><span>  基础：队列可选承载长任务；网关提供 reasoning 别名</span></span>
<span class="line"><span>  交互：展示「待审批」卡；管理员批准后 resume</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_4-3-知识库带引用问答" tabindex="-1">4.3 知识库带引用问答 <a class="header-anchor" href="#_4-3-知识库带引用问答" aria-label="Permalink to &quot;4.3 知识库带引用问答&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：「退货政策第 3 条？」</span></span>
<span class="line"><span>  交互：引用卡、来源列表</span></span>
<span class="line"><span>  应用：Run + 权限上下文注入</span></span>
<span class="line"><span>  Agent：检索 Tool / 固定 RAG Chain（按复杂度）</span></span>
<span class="line"><span>  工作流：通常不需要</span></span>
<span class="line"><span>  数据：文档 ACL、chunk 元数据、Message 中的 citation ids</span></span>
<span class="line"><span>  基础：Embedding 模型别名、向量库连接</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>三条路径共享交互 / 应用 / 数据 / 基础设施；差异集中在 <strong>Agent 是否升级为工作流</strong> 与 <strong>数据实体种类</strong>。</p><h3 id="_4-4-跨层数据只向下携带什么" tabindex="-1">4.4 跨层数据只向下携带什么 <a class="header-anchor" href="#_4-4-跨层数据只向下携带什么" aria-label="Permalink to &quot;4.4 跨层数据只向下携带什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>下行字段</th><th>来源层</th><th>消费层</th><th>禁止事项</th></tr></thead><tbody><tr><td><code>tenantId</code> / <code>userId</code> / <code>roles</code></td><td>应用（鉴权后）</td><td>Agent / 工作流 / 数据查询</td><td>模型参数里「用户自称」覆盖</td></tr><tr><td><code>threadId</code> / <code>runId</code></td><td>应用（创建后）</td><td>全链路 Trace、取消、落库</td><td>UI 本地生成冒充权威 id</td></tr><tr><td><code>alias</code>（模型）</td><td>应用或路由策略</td><td>基础设施 Gateway</td><td>交互层点名供应商 model id</td></tr><tr><td><code>idempotencyKey</code></td><td>交互传入 / 应用校验</td><td>数据与副作用 Tool</td><td>图节点内静默改写键含义</td></tr><tr><td><code>documentAcl</code></td><td>数据</td><td>Agent 检索 Tool</td><td>Prompt 文案代替 ACL</td></tr></tbody></table><p>把「身份、关联 id、幂等键、权限」当成<strong>跨层护照</strong>：护照由应用签发，下层只验证与使用。</p><h2 id="_5-规则与不变量" tabindex="-1">5. 规则与不变量 <a class="header-anchor" href="#_5-规则与不变量" aria-label="Permalink to &quot;5. 规则与不变量&quot;">​</a></h2><h3 id="_5-1-依赖不变量" tabindex="-1">5.1 依赖不变量 <a class="header-anchor" href="#_5-1-依赖不变量" aria-label="Permalink to &quot;5.1 依赖不变量&quot;">​</a></h3><ol><li><strong>交互层不拥有业务真相</strong>：刷新后必须以服务端 Thread/Run/Message 重建。</li><li><strong>应用层是唯一对外协议所有者</strong>：不要让前端解析 LangChain <code>streamEvents</code> 原始名。</li><li><strong>Agent 层不得绕过鉴权 Context</strong>：<code>userId</code> / <code>tenantId</code> 只来自应用注入。</li><li><strong>工作流 Checkpoint ≠ 业务单据</strong>：审批通过后必须写退款单事实表。</li><li><strong>基础设施可替换</strong>：换供应商只改网关注册，不改六层语义。</li></ol><h3 id="_5-2-何时允许「层合并」" tabindex="-1">5.2 何时允许「层合并」 <a class="header-anchor" href="#_5-2-何时允许「层合并」" aria-label="Permalink to &quot;5.2 何时允许「层合并」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>可接受合并</th><th>必须拆回的信号</th></tr></thead><tbody><tr><td>MVP 工作台</td><td>Agent 直接在 Nest Service 内组装</td><td>出现第二套产品事件消费者</td></tr><tr><td>单人 PoC</td><td>暂无独立工作流层</td><td>需要跨天 Interrupt / 多实例恢复</td></tr><tr><td>原型</td><td>前端直连模型（仅本地）</td><td>密钥进入浏览器或要租户隔离</td></tr></tbody></table><p>合并是<strong>临时债</strong>，必须在 ADR 或交付清单中写明复查条件。</p><h2 id="_6-边界、例外与限制" tabindex="-1">6. 边界、例外与限制 <a class="header-anchor" href="#_6-边界、例外与限制" aria-label="Permalink to &quot;6. 边界、例外与限制&quot;">​</a></h2><h3 id="_6-1-与相邻文章的分工" tabindex="-1">6.1 与相邻文章的分工 <a class="header-anchor" href="#_6-1-与相邻文章的分工" aria-label="Permalink to &quot;6.1 与相邻文章的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>本篇</th><th>别篇</th></tr></thead><tbody><tr><td>六层地图</td><td>定义与落点</td><td>—</td></tr><tr><td>Nuxt vs Nest vs LC vs LG</td><td>点到为止</td><td><a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a></td></tr><tr><td>UI / Run / 持久态</td><td>点到为止</td><td><a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">状态所有权</a></td></tr><tr><td>项目拼装验收</td><td>不写步骤</td><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td></tr></tbody></table><h3 id="_6-2-分层模型的限制" tabindex="-1">6.2 分层模型的限制 <a class="header-anchor" href="#_6-2-分层模型的限制" aria-label="Permalink to &quot;6.2 分层模型的限制&quot;">​</a></h3><ul><li>六层是<strong>认知模型</strong>，不是强制六个 npm 包或六个微服务。</li><li>同进程 Nest 内可以有多个 Module 对应不同层，只要依赖方向清晰。</li><li>「工作流层」在知识库路径上可能长期为空实现——空也是显式决策，不是遗忘。</li></ul><h3 id="_6-3-仓库目录与层的推荐映射" tabindex="-1">6.3 仓库目录与层的推荐映射 <a class="header-anchor" href="#_6-3-仓库目录与层的推荐映射" aria-label="Permalink to &quot;6.3 仓库目录与层的推荐映射&quot;">​</a></h3><p>决策层不强制 monorepo 形状，但下列映射有助于评审时「打开文件夹即知所属层」：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/web/          → 交互（Nuxt）</span></span>
<span class="line"><span>apps/api/src/</span></span>
<span class="line"><span>  modules/http/    → 应用（Controller、DTO、Guard）</span></span>
<span class="line"><span>  modules/ai/      → Agent 装配 + 工作流装配（适配器）</span></span>
<span class="line"><span>  modules/domain/  → 数据端口与业务实体</span></span>
<span class="line"><span>  modules/infra/   → Gateway、队列、Redis、Telemetry</span></span>
<span class="line"><span>packages/contracts → 跨层产品事件与 OpenAPI 类型</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>modules/ai</code> 可以同时含 Agent 与 Graph，但<strong>对外</strong>仍只通过应用层 UseCase 暴露；禁止 <code>http</code> 直接深层调用 Graph 内部节点函数绕过用例。</p><h3 id="_6-4-与交付文档的关系" tabindex="-1">6.4 与交付文档的关系 <a class="header-anchor" href="#_6-4-与交付文档的关系" aria-label="Permalink to &quot;6.4 与交付文档的关系&quot;">​</a></h3><p>分层图应出现在项目交付的「架构决策摘要」中：六层各用一句话写所有者与否决项。详细 API 仍指向各模块文章，避免交付文档变成第二份手册。</p><h2 id="_7-可观察示例-分层归属表" tabindex="-1">7. 可观察示例：分层归属表 <a class="header-anchor" href="#_7-可观察示例-分层归属表" aria-label="Permalink to &quot;7. 可观察示例：分层归属表&quot;">​</a></h2><p>以下用售后系统中的具体对象做归属自检（决策级，非实现）：</p><table tabindex="0"><thead><tr><th>对象</th><th>归属层</th><th>判断依据</th></tr></thead><tbody><tr><td>「正在输入…」指示器</td><td>交互</td><td>连接/本地 UX，可丢</td></tr><tr><td><code>run.status = running</code></td><td>数据（经应用写入）</td><td>审计与恢复需要</td></tr><tr><td><code>queryTicket</code> Tool</td><td>Agent</td><td>模型可选调用</td></tr><tr><td><code>pending_approval</code> 图节点</td><td>工作流</td><td>需 Interrupt / Resume</td></tr><tr><td>退款单金额 199</td><td>数据</td><td>财务事实</td></tr><tr><td><code>support-fast</code> 别名</td><td>基础设施</td><td>模型交付</td></tr><tr><td>SSE <code>tool.started</code></td><td>应用→交互契约</td><td>产品事件，非框架私有名</td></tr><tr><td>pgvector 检索结果（带 ACL）</td><td>数据 + Agent 消费</td><td>权限在数据/应用，拼装在 Agent</td></tr></tbody></table><p>若团队对同一对象给出两个归属，说明契约未定——先修分层，再写代码。</p><h3 id="_7-1-反例-错误归属如何拖垮迭代" tabindex="-1">7.1 反例：错误归属如何拖垮迭代 <a class="header-anchor" href="#_7-1-反例-错误归属如何拖垮迭代" aria-label="Permalink to &quot;7.1 反例：错误归属如何拖垮迭代&quot;">​</a></h3><table tabindex="0"><thead><tr><th>错误归属</th><th>后果</th><th>纠正</th></tr></thead><tbody><tr><td>把退款成功写在 assistant 文案里当唯一证据</td><td>财务对账失败、重复退款</td><td>业务表权威 + Message 只引用单号</td></tr><tr><td>在 Nuxt 选模型温度</td><td>无法按租户策略审计</td><td>应用/路由策略 → Gateway 别名</td></tr><tr><td>在 Tool 内直接发 SSE</td><td>多消费者与重连无法复用</td><td>应用层统一适配产品事件</td></tr><tr><td>把 ACL 只写在 System Prompt</td><td>越权检索</td><td>数据层强制过滤后再给模型</td></tr></tbody></table><h3 id="_7-2-正向走查口述稿-售后" tabindex="-1">7.2 正向走查口述稿（售后） <a class="header-anchor" href="#_7-2-正向走查口述稿-售后" aria-label="Permalink to &quot;7.2 正向走查口述稿（售后）&quot;">​</a></h3><p>评审时可要求实现者口述，不得看代码：</p><ol><li>用户点发送后，<strong>哪一层</strong>创建 <code>runId</code>？</li><li>工具查工单时，<code>tenantId</code> 从哪来？</li><li>进入审批挂起时，<strong>哪一层</strong>保存可 resume 的位置？</li><li>批准之后，<strong>哪一层</strong>写出账事实？</li><li>前端刷新后，气泡从哪重建？</li></ol><p>五问都答在「应用 / 数据 / 工作流 / 交互」正确槽位，即分层共识成立。</p><h2 id="_8-验证方法与常见误解" tabindex="-1">8. 验证方法与常见误解 <a class="header-anchor" href="#_8-验证方法与常见误解" aria-label="Permalink to &quot;8. 验证方法与常见误解&quot;">​</a></h2><h3 id="_8-1-分层自检-15-分钟" tabindex="-1">8.1 分层自检（15 分钟） <a class="header-anchor" href="#_8-1-分层自检-15-分钟" aria-label="Permalink to &quot;8.1 分层自检（15 分钟）&quot;">​</a></h3><ol><li>画出用户一句话到最终落库的路径，标注穿过的层。</li><li>任选一个变更：「换备用模型供应商」——应只动基础设施（及网关 ADR），列出被误伤的文件则失败。</li><li>任选一个变更：「审批文案按钮改色」——应只动交互层。</li><li>确认 Checkpoint 中没有「唯一的退款成功标志」。</li><li>打开 <code>packages/contracts</code>（或等价目录）：产品事件名是否独立于 LangChain 事件名。</li></ol><h3 id="_8-2-常见误解" tabindex="-1">8.2 常见误解 <a class="header-anchor" href="#_8-2-常见误解" aria-label="Permalink to &quot;8.2 常见误解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>误解</th><th>纠正</th></tr></thead><tbody><tr><td>「有 LangGraph 就不需要应用层」</td><td>图不懂租户鉴权与产品 SSE 协议</td></tr><tr><td>「Agent 层等于整个后端」</td><td>Agent 是编排；用例与持久化仍在应用/数据</td></tr><tr><td>「分层就要拆微服务」</td><td>先逻辑分层；部署拓扑另做决策</td></tr><tr><td>「知识库是第七层」</td><td>检索是数据能力 + Agent/Chain 消费，不另开层</td></tr><tr><td>「基础设施层可以随便调用业务表」</td><td>可以提供连接，但业务写入规则仍归数据/应用用例</td></tr></tbody></table><h3 id="_8-3-读完下一篇" tabindex="-1">8.3 读完下一篇 <a class="header-anchor" href="#_8-3-读完下一篇" aria-label="Permalink to &quot;8.3 读完下一篇&quot;">​</a></h3><p>能说出六层后，下一步明确<strong>四个框架各自落在哪一层、允许谁依赖谁</strong>：<a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a>。</p>`,89)])])}const u=a(d,[["render",r]]);export{b as __pageData,u as default};
